// Devis signes (filtre natif Interfast toPlan) moins ceux qui sont deja pris en charge :
//  1. une intervention porte le n° de devis (reference externe / secondReference, ou n° dans le titre) ;
//  2. ou une intervention existe chez le meme client a partir du jour de la signature ;
//  3. ou le devis est deja facture a plus de 80 % (travaux faits).
// Lecture seule Interfast, aucune IA.
const DEPUIS = '2026-01-01';           // devis signes avant cette date ignores (anti-cimetiere)
// Repartition : Christophe planifie depannages, entretiens, reparations et petits travaux ; Laurent les nouvelles installations.
const CHRISTOPHE = /entretien|maintenance|contrat|d[ée]pannage|r[ée]paration|relevage|fuite|diagnostic|nettoyage|filtre|r[ée]vision|recharge|thermostat|compresseur|carte|moteur|ventilat|condensateur|sonde|vanne|pi[eè]ce/i;
const LAURENT = /install|\bpose\b|nouvel|split|multi|gainable|\bvrv\b|\bvrf\b|\bdrv\b|\bpac\b|pompe [àa] chaleur|climatisation|cassette|console|murale|yukai|haori|daikin|toshiba|mitsubishi|hitachi|fujitsu|haier|ballon|chauffe-eau|vmc|plancher|chaudi[eè]re/i;
const responsable = t => CHRISTOPHE.test(t) ? 'christophe' : (LAURENT.test(t) ? 'laurent' : 'christophe');
const now = DateTime.now().toUTC().toISO();
const body = $('Devis signes a planifier (Interfast)').first().json || {};
if (!Array.isArray(body.items)) throw new Error('Reponse Interfast devis inattendue : rien n est modifie');
const liste = body.items.filter(d => d && d.reference && (d.signedAt || d.updatedAt) >= DEPUIS && !d.isTestData && !d.isTemplate);
const parRef = {};
const parClient = {};
const vus = new Set();
for (const it of $('Interfast - interventions').all()) {
  for (const ev of (it.json.items || [])) {
    if (!ev || vus.has(String(ev.id))) continue;
    vus.add(String(ev.id));
    if (ev.lifecycleState === 'cancelled' || ev.category === 'task') continue;
    const nom = ev.reference || String(ev.id);
    const txt = [ev.secondReference, ev.title].filter(Boolean).join(' ').toUpperCase();
    for (const m of txt.matchAll(/\bD[CE]\s?\d{3,6}\b/g)) { const r = m[0].replace(/\s/g, ''); if (!parRef[r]) parRef[r] = nom; }
    const cid = ev.client && ev.client.id ? String(ev.client.id) : '';
    if (cid && ev.start) (parClient[cid] = parClient[cid] || []).push({ start: ev.start, nom });
  }
}
function lien(d) {
  const ref = String(d.reference).toUpperCase();
  if (parRef[ref]) return parRef[ref];
  const cid = d.client && d.client.id ? String(d.client.id) : '';
  const depuis = DateTime.fromISO(d.signedAt || d.updatedAt).minus({ days: 1 }).toUTC().toISO();
  const ev = (parClient[cid] || []).filter(e => e.start >= depuis).sort((a, b) => a.start < b.start ? -1 : 1)[0];
  if (ev) return ev.nom;
  if (Number(d.amountVAT) > 0 && Number(d.balance) <= 0.2 * Number(d.amountVAT)) return 'facture';
  return '';
}
const table = {};
for (const it of $('Lire table').all()) { const r = it.json || {}; if (r.reference) table[r.reference] = r; }
const out = [];
const enCours = new Set();
const pris = {};
for (const d of liste) {
  const ref = String(d.reference).toUpperCase();
  const l = lien(d);
  if (l) { pris[ref] = l; continue; }
  enCours.add(ref);
  const ex = table[ref];
  const c = d.client || {};
  out.push({ json: {
    reference: ref, devis_id: String(d.id), titre: String(d.name || '').slice(0, 200),
    client: String(c.name || '').trim(), client_id: String(c.id || ''), ville: String(d.addressCity || ''),
    telephone: String(c.phoneNumber || ''), signe_le: d.signedAt || d.updatedAt,
    responsable: responsable(String(d.name || '')),
    planifie: false, planifie_le: null, intervention_ref: '', vu_le: (ex && ex.vu_le) || now, source: 'interfast'
  } });
}
// Lignes encore ouvertes dans la table mais sorties de la liste : planifiees (ou devis annule / facture).
// Exception : les devis acceptes par mail (source = mail) restent tant qu'aucune intervention n'existe
// (le workflow « Devis acceptes par mail » les ferme si le devis est annule, refuse ou solde).
for (const [ref, r] of Object.entries(table)) {
  if (r.planifie || enCours.has(ref)) continue;
  if (r.source === 'mail') {
    const l = parRef[ref] || ((parClient[String(r.client_id || '')] || []).filter(e => e.start >= DateTime.fromISO(String(r.signe_le || now)).minus({ days: 1 }).toUTC().toISO()).sort((a, b) => a.start < b.start ? -1 : 1)[0] || {}).nom;
    if (l) out.push({ json: { reference: ref, planifie: true, planifie_le: now, intervention_ref: l } });
    continue;
  }
  out.push({ json: { reference: ref, planifie: true, planifie_le: now, intervention_ref: pris[ref] || '' } });
}
return out;

const debut = DateTime.now().minus({ months: 8 }).toUTC().toISO();
const fin = DateTime.now().plus({ months: 13 }).toUTC().toISO();
return Array.from({ length: 15 }, (_, i) => ({ json: { page: i, debut, fin } }));
